import { useEffect, useState } from 'react';
import { fetchOpenMeteoJson, roundCoord } from '../../utils/openMeteoClient';

/**
 * Fetch 48-hour wave/weather forecast from Open-Meteo API
 * Covers: wave height, wind speed, water temp, wave period
 * Falls back to simulated data on error
 */
export function useForecastData(lat = 32.87, lon = -117.26) {
    const [forecastData, setForecastData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchForecast = async () => {
            try {
                setLoading(true);
                setError(null);

                // Open-Meteo forecast API (free, no key required)
                const baseUrl = 'https://api.open-meteo.com/v1/forecast';
                const safeLat = roundCoord(lat, 3);
                const safeLon = roundCoord(lon, 3);
                const params = new URLSearchParams({
                    latitude: safeLat,
                    longitude: safeLon,
                    hourly: 'wave_height,wave_period,wind_speed_10m,temperature_2m',
                    timezone: 'America/Los_Angeles',
                    forecast_days: 2, // 48 hours
                });

                const url = `${baseUrl}?${params.toString()}`;
                const data = await fetchOpenMeteoJson(url, {
                    cacheKey: `forecast:${safeLat}:${safeLon}`,
                    ttlMs: 30 * 60 * 1000,
                    allowStaleOnError: true
                });

                if (!data.hourly || !data.hourly.time) {
                    throw new Error('Invalid forecast response structure');
                }

                // Parse API response into forecast format
                const forecast = data.hourly.time.map((timeStr, i) => {
                    const date = new Date(timeStr);
                    const hour = date.getHours();
                    const isTonight = date.getDate() === new Date().getDate();
                    const dayLabel = isTonight ? 'Today' : 'Tomorrow';

                    // Convert units: meters→feet, m/s→knots, Celsius→Fahrenheit
                    const waveHeightMeters = data.hourly.wave_height[i] || 0.5;
                    const waveHeightFeet = waveHeightMeters * 3.28084;

                    const windSpeedMs = data.hourly.wind_speed_10m[i] || 5;
                    const windSpeedKnots = windSpeedMs * 1.94384;

                    const tempCelsius = data.hourly.temperature_2m[i] || 18;
                    const wavePeriodSeconds = data.hourly.wave_period[i] || 8;

                    const timeStr2 = `${(hour % 12 || 12).toString().padStart(2, '0')}:00 ${hour < 12 ? 'AM' : 'PM'}`;

                    return {
                        time: timeStr2,
                        shortTime: `${hour}h`,
                        swellHeight: Math.round(waveHeightFeet * 10) / 10,
                        wind: Math.round(windSpeedKnots),
                        waterTemp: tempCelsius,
                        period: Math.round(wavePeriodSeconds * 10) / 10,
                        hour: i,
                        day: dayLabel,
                    };
                });

                setForecastData(forecast);
            } catch (err) {
                setError(err.message);
                // Fallback: return null so ForecastChart will generate simulated data
                setForecastData(null);
            } finally {
                setLoading(false);
            }
        };

        fetchForecast();
    }, [lat, lon]);

    return { forecastData, loading, error };
}
